package dev.hrutvik.billing.api;
import dev.hrutvik.billing.metering.RealtimeUsageUnavailable; import dev.hrutvik.billing.usage.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.Map;
@RestControllerAdvice
public class ApiExceptionHandler {
 @ExceptionHandler(RuntimeException.class) ResponseEntity<Map<String,Object>> handle(RuntimeException e){HttpStatus s=e instanceof RealtimeUsageUnavailable?HttpStatus.SERVICE_UNAVAILABLE:e.getClass().getSimpleName().equals("IdempotencyConflict")||e.getClass().getSimpleName().equals("CreditConflictException")?HttpStatus.CONFLICT:e instanceof IllegalArgumentException?HttpStatus.BAD_REQUEST:e.getClass().getSimpleName().equals("UnknownMeter")?HttpStatus.UNPROCESSABLE_ENTITY:e.getClass().getSimpleName().equals("EventOutsideWindow")?HttpStatus.UNPROCESSABLE_ENTITY:HttpStatus.INTERNAL_SERVER_ERROR; return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"code",e.getClass().getSimpleName().toUpperCase(),"message",e.getMessage()));}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"code","VALIDATION_ERROR","message","Invalid usage event"));}
}
